import { action, api, app, page, query, route } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage, SignupPage } from "./src/pages/auth" with { type: "ref" };
import { getApiKeys } from "./src/queries" with { type: "ref" };
import { createApiKey, deleteApiKey } from "./src/actions" with { type: "ref" };
import { apiRequestHandler } from "./src/apis" with { type: "ref" };
import { devSeedSimple } from "./src/dbSeeds" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  db: {
    seeds: [devSeedSimple],
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),

    query(getApiKeys, { entities: ["ApiKey", "ApiLog"] }),
    action(createApiKey, { entities: ["ApiKey"] }),
    action(deleteApiKey, { entities: ["ApiKey", "ApiLog"] }),

    api("GET", "/api/request", apiRequestHandler, {
      entities: ["ApiKey", "ApiLog"],
      auth: false,
    }),
  ],
});

import { HttpError } from "wasp/server";
import type { GetApiKeys } from "wasp/server/operations";
import type { ApiKey, ApiLog } from "wasp/entities";

type ApiKeyWithLogs = ApiKey & { logs: ApiLog[] };

export const getApiKeys: GetApiKeys<void, ApiKeyWithLogs[]> = async (
  _args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  return context.entities.ApiKey.findMany({
    where: { userId: context.user.id },
    include: {
      logs: {
        orderBy: { timestamp: "desc" },
      },
    },
    orderBy: { createdAt: "desc" },
  });
};

import { randomUUID } from "crypto";
import { HttpError } from "wasp/server";
import type { CreateApiKey, DeleteApiKey } from "wasp/server/operations";
import type { ApiKey } from "wasp/entities";

type CreateApiKeyInput = {
  name: string;
  quota: number;
};

export const createApiKey: CreateApiKey<CreateApiKeyInput, ApiKey> = async (
  args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const key = `sk_${randomUUID().replace(/-/g, "")}`;

  return context.entities.ApiKey.create({
    data: {
      key,
      name: args.name,
      quota: args.quota,
      usage: 0,
      userId: context.user.id,
    },
  });
};

type DeleteApiKeyInput = {
  id: number;
};

export const deleteApiKey: DeleteApiKey<DeleteApiKeyInput, void> = async (
  args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const apiKey = await context.entities.ApiKey.findUnique({
    where: { id: args.id },
  });

  if (!apiKey || apiKey.userId !== context.user.id) {
    throw new HttpError(404, "API key not found");
  }

  await context.entities.ApiKey.delete({
    where: { id: args.id },
  });
};

import type { ApiRequestHandler } from "wasp/server/api";

const ENDPOINT_LABEL = "GET /api/request";
const RATE_LIMIT_WINDOW_MS = 10 * 1000;
const RATE_LIMIT_MAX_REQUESTS = 3;

function extractApiKey(req: Parameters<ApiRequestHandler>[0]): string | null {
  const authHeader = req.headers["authorization"];
  if (typeof authHeader === "string" && authHeader.startsWith("Bearer ")) {
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length > 0) {
      return token;
    }
  }

  const queryKey = req.query["apiKey"];
  if (typeof queryKey === "string" && queryKey.length > 0) {
    return queryKey;
  }

  return null;
}

export const apiRequestHandler: ApiRequestHandler = async (
  req,
  res,
  context,
) => {
  res.set("Access-Control-Allow-Origin", "*");

  const providedKey = extractApiKey(req);

  if (!providedKey) {
    res.status(401).json({ error: "Invalid API key" });
    return;
  }

  const apiKey = await context.entities.ApiKey.findUnique({
    where: { key: providedKey },
  });

  if (!apiKey) {
    res.status(401).json({ error: "Invalid API key" });
    return;
  }

  const windowStart = new Date(Date.now() - RATE_LIMIT_WINDOW_MS);
  const recentRequestCount = await context.entities.ApiLog.count({
    where: {
      apiKeyId: apiKey.id,
      timestamp: { gte: windowStart },
    },
  });

  if (recentRequestCount >= RATE_LIMIT_MAX_REQUESTS) {
    await context.entities.ApiLog.create({
      data: {
        endpoint: ENDPOINT_LABEL,
        status: 429,
        apiKeyId: apiKey.id,
      },
    });
    res.status(429).json({ error: "Rate limit exceeded" });
    return;
  }

  if (apiKey.usage >= apiKey.quota) {
    await context.entities.ApiLog.create({
      data: {
        endpoint: ENDPOINT_LABEL,
        status: 429,
        apiKeyId: apiKey.id,
      },
    });
    res.status(429).json({ error: "Quota exceeded" });
    return;
  }

  const updatedApiKey = await context.entities.ApiKey.update({
    where: { id: apiKey.id },
    data: { usage: { increment: 1 } },
  });

  await context.entities.ApiLog.create({
    data: {
      endpoint: ENDPOINT_LABEL,
      status: 200,
      apiKeyId: apiKey.id,
    },
  });

  res.status(200).json({
    success: true,
    message: "Request successful",
    usage: updatedApiKey.usage,
    quota: updatedApiKey.quota,
  });
};

import type { DbSeedFn } from "wasp/server";
import { sanitizeAndSerializeProviderData } from "wasp/server/auth";

export const devSeedSimple: DbSeedFn = async (prisma) => {
  const username = "devuser";
  const password = "password123";

  const existing = await prisma.user.findUnique({
    where: { username },
  });

  if (existing) {
    return;
  }

  await prisma.user.create({
    data: {
      username,
      password: await sanitizeAndSerializeProviderData<"username">({
        hashedPassword: password,
      }).then((data) => JSON.stringify(data)),
      auth: {
        create: {
          identities: {
            create: {
              providerName: "username",
              providerUserId: username,
              providerData: await sanitizeAndSerializeProviderData<"username">({
                hashedPassword: password,
              }),
            },
          },
        },
      },
    },
  });
};

import type { DbSeedFn } from "wasp/server";
import { sanitizeAndSerializeProviderData } from "wasp/server/auth";

export const devSeedSimple: DbSeedFn = async (prisma) => {
  const username = "devuser";
  const password = "password123";

  const existing = await prisma.user.findUnique({
    where: { username },
  });

  if (existing) {
    return;
  }

  const providerData = await sanitizeAndSerializeProviderData<"username">({
    hashedPassword: password,
  });

  await prisma.user.create({
